WITH promo_agg AS ( SELECT p.p_promo_id, p.p_promo_name, p.p_discount_active, COUNT(ss.ss_ticket_number) AS sales_transactions, SUM(ss.ss_ext_sales_price) AS total_sales_amount, SUM(ss.ss_ext_discount_amt) AS total_discount_amount, AVG(ss.ss_ext_discount_amt) AS avg_discount_per_tx, SUM(ss.ss_net_profit) AS total_profit FROM store_sales ss JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk JOIN date_dim sale_date ON ss.ss_sold_date_sk = sale_date.d_date_sk JOIN date_dim start_date ON p.p_start_date_sk = start_date.d_date_sk JOIN date_dim end_date ON p.p_end_date_sk = end_date.d_date_sk WHERE sale_date.d_date BETWEEN start_date.d_date AND end_date.d_date GROUP BY p.p_promo_id, p.p_promo_name, p.p_discount_active ) SELECT p_promo_id, p_promo_name, sales_transactions, total_sales_amount, total_discount_amount, avg_discount_per_tx, total_profit, CASE WHEN p_discount_active = 'Y' THEN 'Active' ELSE 'Inactive' END AS discount_status, DENSE_RANK() OVER (ORDER BY total_sales_amount DESC) AS sales_rank, RANK() OVER (ORDER BY total_profit DESC) AS profit_rank FROM promo_agg ORDER BY sales_rank LIMIT 20
